// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(256000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const errors: string[] = [];
    page.on('pageerror', (err) => errors.push(err.message));

    await page.goto(baseUrl);
    // Wait for network activities to finish
    await page.waitForTimeout(5000);

    await page.getByRole("textbox", { name: "Search products..." }).fill("xyznonexistent");
    await page.getByRole("button", { name: "Search" }).click();
    await expect(page).toHaveURL(/search\?q=xyznonexistent/);
    await expect(page.getByText("No products found for ")).toContainText('No products found for "xyznonexistent"');
    await expect(page.getByRole("link", { name: "Continue Shopping" })).toBeVisible();
    await expect(page.getByRole("textbox", { name: "Search products..." })).toHaveValue("xyznonexistent");
    expect(errors).toHaveLength(0);
});
